18	const CONTENT_AVERAGE_CHAR_WIDTH = 7;
19	const CONTENT_LINE_HEIGHT = 22;
20	const CONTENT_MIN_CHARS_PER_LINE = 18;
21	
22	const MARKDOWN_IMAGE_HEIGHT = 220;
23	const SINGLE_IMAGE_HEIGHT = 260;
24	const SINGLE_VIDEO_ASPECT_RATIO = 9 / 16;
25	const TWO_VISUAL_ITEMS_HEIGHT = 240;
26	const MOSAIC_VISUAL_ITEMS_HEIGHT = 288;
27	const SIX_VISUAL_ITEMS_HEIGHT = 320;
28	const ATTACHMENT_SECTION_HEADER_HEIGHT = 36;
29	const ATTACHMENT_SECTION_PADDING = 16;
30	const ATTACHMENT_SECTION_GAP = 8;
31	const AUDIO_ATTACHMENT_ROW_HEIGHT = 92;
32	const DOCUMENT_ATTACHMENT_ROW_HEIGHT = 64;
33	
34	const REACTION_ROW_HEIGHT = 28;
35	const COMMENT_PREVIEW_HEADER_HEIGHT = 20;
36	const COMMENT_PREVIEW_ROW_HEIGHT = 44;
37	const COMMENT_PREVIEW_VERTICAL_PADDING = 20;
38	const MAX_VISIBLE_COMMENT_PREVIEWS = 3;
39	
40	const estimateWrappedTextHeight = (content: string, columnWidth: number): number => {
41	  const textWidth = Math.max(1, columnWidth - CONTENT_HORIZONTAL_PADDING);
42	  const charsPerLine = Math.max(CONTENT_MIN_CHARS_PER_LINE, Math.floor(textWidth / CONTENT_AVERAGE_CHAR_WIDTH));
43	  const lineCount = content.split("\n").reduce((total, line) => total + Math.max(1, Math.ceil(line.length / charsPerLine)), 0);
44	  return lineCount * CONTENT_LINE_HEIGHT;
45	};
46	
47	const countMarkdownImages = (content: string): number => {
48	  const markdownImages = content.match(/!\[[^\]]*]\([^)]+\)/g)?.length ?? 0;
49	  const htmlImages = content.match(/<img\s/gi)?.length ?? 0;
50	  return markdownImages + htmlImages;
51	};
52	
53	const isVisualAttachment = (attachment: Attachment): boolean => {
54	  const type = getAttachmentType(attachment);
55	  return type === "image/*" || type === "video/*" || isMotionAttachment(attachment);
56	};
57	
58	const isAudioAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "audio/*";
59	
60	const estimateVisualGalleryHeight = (visualAttachments: Attachment[], columnWidth: number): number => {
61	  const count = buildAttachmentVisualItems(visualAttachments).length;
62	  if (count === 0) return 0;
63	  if (count === 1) {
64	    const type = getAttachmentType(visualAttachments[0]!);
65	    return type === "video/*" ? Math.round(columnWidth * SINGLE_VIDEO_ASPECT_RATIO) : SINGLE_IMAGE_HEIGHT;
66	  }
67	  if (count === 2) return TWO_VISUAL_ITEMS_HEIGHT;
68	  if (count <= 4) return MOSAIC_VISUAL_ITEMS_HEIGHT;
69	  return SIX_VISUAL_ITEMS_HEIGHT;
70	};
71	
72	const estimateAttachmentSectionHeight = (attachments: Attachment[], columnWidth: number): number => {
73	  if (attachments.length === 0) return 0;
74	
75	  const visual = attachments.filter(isVisualAttachment);
76	  const audio = attachments.filter(isAudioAttachment);
77	  const docs = attachments.filter((attachment) => !isVisualAttachment(attachment) && !isAudioAttachment(attachment));
78	  const contentParts = [
79	    estimateVisualGalleryHeight(visual, columnWidth),
80	    audio.length > 0 ? audio.length * AUDIO_ATTACHMENT_ROW_HEIGHT + Math.max(0, audio.length - 1) * ATTACHMENT_SECTION_GAP : 0,
81	    docs.length > 0 ? docs.length * DOCUMENT_ATTACHMENT_ROW_HEIGHT + Math.max(0, docs.length - 1) * ATTACHMENT_SECTION_GAP : 0,
82	  ].filter((height) => height > 0);
83	
84	  const contentHeight =
85	    contentParts.reduce((total, height) => total + height, 0) + Math.max(0, contentParts.length - 1) * ATTACHMENT_SECTION_GAP;
86	  return ATTACHMENT_SECTION_HEADER_HEIGHT + ATTACHMENT_SECTION_PADDING + contentHeight;
87	};
88	
89	const countCommentRelations = (memo: Memo): number =>
90	  (memo.relations ?? []).filter((relation) => relation.type === MemoRelation_Type.COMMENT && relation.relatedMemo?.name === memo.name)
91	    .length;
92	
93	const estimateCommentPreviewHeight = (memo: Memo): number => {
94	  const visibleCommentCount = Math.min(countCommentRelations(memo), MAX_VISIBLE_COMMENT_PREVIEWS);
95	  if (visibleCommentCount === 0) return 0;
96	  return COMMENT_PREVIEW_VERTICAL_PADDING + COMMENT_PREVIEW_HEADER_HEIGHT + visibleCommentCount * COMMENT_PREVIEW_ROW_HEIGHT;
97	};
98	
99	export const estimateMemoCardHeight = (memo: Memo, { columnWidth }: EstimateMemoCardHeightOptions): number => {
100	  const content = memo.content ?? "";
101	  const contentHeight = estimateWrappedTextHeight(content, columnWidth) + countMarkdownImages(content) * MARKDOWN_IMAGE_HEIGHT;
102	  const attachmentHeight = estimateAttachmentSectionHeight(memo.attachments ?? [], columnWidth);
103	  const bodyHeight = contentHeight + attachmentHeight + (contentHeight > 0 && attachmentHeight > 0 ? CARD_SECTION_GAP : 0);
104	  const compactBodyHeight = bodyHeight > CLAMP_TRIGGER_HEIGHT_PX ? CLAMP_PREVIEW_HEIGHT_PX + SHOW_MORE_BUTTON_HEIGHT : bodyHeight;
105	  const reactionHeight = (memo.reactions ?? []).length > 0 ? CARD_SECTION_GAP + REACTION_ROW_HEIGHT : 0;
106	
107	  return (
108	    CARD_VERTICAL_PADDING + CARD_HEADER_HEIGHT + CARD_SECTION_GAP + compactBodyHeight + reactionHeight + estimateCommentPreviewHeight(memo)
109	  );
110	};
